package io.kimpton.accountdataexporter;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class AccountDataExporterTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(AccountDataExporterPlugin.class);
		RuneLite.main(args);
	}
}

package io.kimpton.accountdataexporter;

import com.google.gson.Gson;
import io.kimpton.accountdataexporter.model.Container;
import io.kimpton.accountdataexporter.model.ItemStack;
import io.kimpton.accountdataexporter.model.Snapshot;
import java.util.Collections;
import org.junit.Assert;
import org.junit.Test;

/** Guards the assumption the cache-seeding path relies on: Lombok @Value models (no no-arg
 *  constructor, final fields) round-trip through Gson without data loss. */
public class ModelSerializationTest
{
	private final Gson gson = new Gson();

	@Test
	public void containerRoundTrips()
	{
		Container original = new Container(true, false, 123L, 4567L, 1,
			Collections.singletonList(new ItemStack(0, 995, "Coins", 4567, 1, 4567L, 1, 4567L)));

		Container restored = gson.fromJson(gson.toJson(original), Container.class);

		Assert.assertEquals(original, restored);
		Assert.assertTrue(restored.isLoaded());
		Assert.assertEquals(4567L, restored.getValue());
		Assert.assertEquals("Coins", restored.getItems().get(0).getName());
	}

	@Test
	public void disabledSectionsAreOmitted()
	{
		Snapshot snapshot = Snapshot.builder()
			.schemaVersion("1.0.1")
			.rsn("Zezima")
			.build();

		String json = gson.toJson(snapshot);

		// Null sections must not appear as keys, so consumers can treat absent as "not exported".
		Assert.assertFalse(json.contains("\"slayer\""));
		Assert.assertFalse(json.contains("\"bank\""));
		Assert.assertTrue(json.contains("\"rsn\":\"Zezima\""));
	}
}

package io.kimpton.accountdataexporter;

import io.kimpton.accountdataexporter.model.AchievementDiaries;
import io.kimpton.accountdataexporter.model.DiaryRegion;
import io.kimpton.accountdataexporter.model.HunterRumours;
import io.kimpton.accountdataexporter.model.RumourAssignment;
import io.kimpton.accountdataexporter.model.SlayerBlockSlot;
import io.kimpton.accountdataexporter.model.SlayerMasterBlocks;
import io.kimpton.accountdataexporter.model.SlayerState;
import io.kimpton.accountdataexporter.model.SlayerTask;
import io.kimpton.accountdataexporter.model.Snapshot;
import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Desktop;
import java.awt.Dimension;
import java.awt.Rectangle;
import java.io.File;
import java.io.UnsupportedEncodingException;
import java.net.URLEncoder;
import java.time.LocalTime;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.ImageIcon;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.Scrollable;
import javax.swing.SwingConstants;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.LinkBrowser;

/** Compact status panel: export destination + last export, the player's slayer
 *  block lists per master (each creature a wiki-linked button; empty and
 *  locked slots shown like the companion web UI), hunter rumours across every
 *  master, and a Buy Me a Coffee button in the top right. Text wraps — the
 *  panel only ever scrolls vertically. */
@Slf4j
class AccountDataExporterPanel extends PluginPanel
{
	private static final String COFFEE_URL = "https://buymeacoffee.com/kimpton";
	private static final String WIKI_SEARCH = "https://oldschool.runescape.wiki/w/Special:Search?search=";

	private static final String[] MASTER_KEYS = {
		"turael", "mazchna", "vannaka", "chaeldar", "konar", "nieve", "duradel", "krystilia",
	};

	private final JLabel accountLabel = smallLabel("Account: —", ColorScheme.LIGHT_GRAY_COLOR);
	private final JLabel lastExportLabel = smallLabel("No export yet this session.", ColorScheme.MEDIUM_GRAY_COLOR);
	private final JPanel slayerSection = column();
	private final JPanel rumourSection = column();
	private JScrollPane scroll;

	// Section content fingerprints: rebuilding tears the sections down (which
	// blinks and resets the scrollbar), so only rebuild when the data changed.
	private String slayerKey = "";
	private String rumourKey = "";

	AccountDataExporterPanel(File exportDirectory)
	{
		super(false);
		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		JPanel content = column();
		content.setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));
		content.setBackground(ColorScheme.DARK_GRAY_COLOR);

		// Header: title left, coffee-mug support button pinned top right.
		JPanel header = new JPanel(new BorderLayout());
		header.setOpaque(false);
		header.setAlignmentX(Component.LEFT_ALIGNMENT);
		JLabel title = new JLabel("Account Data Exporter");
		title.setForeground(ColorScheme.BRAND_ORANGE);
		header.add(title, BorderLayout.WEST);
		JButton coffee = new JButton(new ImageIcon(ImageUtil.loadImageResource(AccountDataExporterPanel.class, "coffee.png")));
		coffee.setToolTipText("Enjoying the plugin? Buy me a coffee");
		coffee.setCursor(new Cursor(Cursor.HAND_CURSOR));
		coffee.setBorder(BorderFactory.createEmptyBorder(2, 2, 2, 2));
		coffee.setContentAreaFilled(false);
		coffee.setFocusPainted(false);
		coffee.addActionListener(e -> LinkBrowser.browse(COFFEE_URL));
		header.add(coffee, BorderLayout.EAST);
		content.add(header);
		content.add(Box.createVerticalStrut(10));

		content.add(sectionTitle("Export"));
		content.add(wrapLabel(exportDirectory.getAbsolutePath(), ColorScheme.MEDIUM_GRAY_COLOR));
		content.add(Box.createVerticalStrut(4));
		JButton open = new JButton("Open export folder");
		open.setFocusPainted(false);
		open.setFont(FontManager.getRunescapeFont());
		open.setAlignmentX(Component.LEFT_ALIGNMENT);
		open.addActionListener(e -> openFolder(exportDirectory));
		content.add(open);
		content.add(Box.createVerticalStrut(4));
		content.add(accountLabel);
		content.add(lastExportLabel);
		content.add(Box.createVerticalStrut(10));

		content.add(sectionTitle("Slayer blocks"));
		slayerSection.add(smallLabel("Waiting for the first export…", ColorScheme.MEDIUM_GRAY_COLOR));
		content.add(slayerSection);
		content.add(Box.createVerticalStrut(10));
		content.add(sectionTitle("Hunter rumours"));
		rumourSection.add(smallLabel("Waiting for the first export…", ColorScheme.MEDIUM_GRAY_COLOR));
		content.add(rumourSection);

		// Vertical-only scrolling: the wrapper tracks the viewport width so long
		// text wraps instead of pushing content (and the coffee button) off-screen.
		ScrollableColumn north = new ScrollableColumn();
		north.add(content, BorderLayout.NORTH);
		scroll = new JScrollPane(north,
			JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED, JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.setBorder(null);
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		add(scroll, BorderLayout.CENTER);
	}

	/** Called on the EDT after each snapshot write. Sections are only rebuilt
	 *  when their data actually changed, and the scroll position is preserved —
	 *  so routine exports don't blink or jump the panel. */
	void update(Snapshot snapshot)
	{
		accountLabel.setText("Account: " + snapshot.getRsn());
		lastExportLabel.setText("Last export: " + LocalTime.now().withNano(0));

		// Lombok @Value toString covers every field, making a cheap change key.
		String sk = String.valueOf(snapshot.getSlayer())
			+ (snapshot.getQuests() != null ? snapshot.getQuests().getQuestPoints() : -1)
			+ lumbridgeEliteDone(snapshot.getAchievementDiaries());
		String rk = String.valueOf(snapshot.getHunterRumours());
		boolean changed = false;
		if (!sk.equals(slayerKey))
		{
			slayerKey = sk;
			rebuildSlayer(snapshot);
			changed = true;
		}
		if (!rk.equals(rumourKey))
		{
			rumourKey = rk;
			rebuildRumours(snapshot.getHunterRumours());
			changed = true;
		}
		if (changed)
		{
			final int pos = scroll.getVerticalScrollBar().getValue();
			revalidate();
			repaint();
			javax.swing.SwingUtilities.invokeLater(() -> scroll.getVerticalScrollBar().setValue(pos));
		}
	}

	private void rebuildSlayer(Snapshot snapshot)
	{
		SlayerState slayer = snapshot.getSlayer();
		slayerSection.removeAll();
		if (slayer == null)
		{
			slayerSection.add(smallLabel("Slayer section is disabled in the config.", ColorScheme.MEDIUM_GRAY_COLOR));
			return;
		}
		SlayerTask task = slayer.getCurrentTask();
		if (task != null && task.isHasTask())
		{
			String name = orId(task.getName(), task.getTaskId());
			JButton t = linkButton("Task: " + task.getAmountRemaining() + "× " + name, wikiSearchUrl(name));
			t.setBorder(BorderFactory.createEmptyBorder(1, 0, 1, 2));
			slayerSection.add(t);
			if (task.getAreaName() != null)
			{
				slayerSection.add(slotNote(task.getAreaName()));
			}
			slayerSection.add(Box.createVerticalStrut(4));
		}

		// Slot gating, like the companion web UI: one block slot per 50 quest
		// points (six slots → 300 QP), the diary slot needs Elite Lumbridge &
		// Draynor. QP is our own export (0.6.1+).
		int qp = snapshot.getQuests() != null ? snapshot.getQuests().getQuestPoints() : -1;
		boolean diaryDone = lumbridgeEliteDone(snapshot.getAchievementDiaries());

		if (slayer.getBlockLists() == null || slayer.getBlockLists().isEmpty())
		{
			slayerSection.add(smallLabel("No block-list data yet.", ColorScheme.MEDIUM_GRAY_COLOR));
			return;
		}
		for (String key : MASTER_KEYS)
		{
			SlayerMasterBlocks blocks = slayer.getBlockLists().get(key);
			if (blocks == null)
			{
				continue;
			}
			String master = key.equals("konar") ? "Konar" : Character.toUpperCase(key.charAt(0)) + key.substring(1);
			JButton mb = linkButton(master, wikiSearchUrl(master));
			mb.setForeground(ColorScheme.BRAND_ORANGE);
			mb.setBorder(BorderFactory.createEmptyBorder(1, 0, 1, 2));
			slayerSection.add(mb);
			addSlotRows(blocks.getSlots(), qp);
			SlayerBlockSlot diary = blocks.getDiarySlot();
			if (diary != null)
			{
				if (diary.isBlocked())
				{
					slayerSection.add(creatureButton(orId(diary.getName(), diary.getTaskId())));
				}
				else if (!diaryDone)
				{
					slayerSection.add(slotNote("🔒 Diary slot — Elite Lumbridge & Draynor"));
				}
				else
				{
					slayerSection.add(slotNote("Diary slot — empty"));
				}
			}
			slayerSection.add(Box.createVerticalStrut(6));
		}
	}

	private void addSlotRows(List<SlayerBlockSlot> slots, int qp)
	{
		if (slots == null)
		{
			return;
		}
		for (SlayerBlockSlot slot : slots)
		{
			if (slot == null)
			{
				continue;
			}
			if (slot.isBlocked())
			{
				slayerSection.add(creatureButton(orId(slot.getName(), slot.getTaskId())));
				continue;
			}
			int need = slot.getSlot() * 50;
			if (qp >= 0 && qp < need)
			{
				slayerSection.add(slotNote("🔒 Slot " + slot.getSlot() + " — " + need + " quest points"));
			}
			else
			{
				slayerSection.add(slotNote("Slot " + slot.getSlot() + " — empty"));
			}
		}
	}

	private void rebuildRumours(HunterRumours rumours)
	{
		rumourSection.removeAll();
		if (rumours == null || !rumours.isAvailable())
		{
			rumourSection.add(wrapLabel("No Hunter Rumours data (needs the Hunter Rumours plugin).", ColorScheme.MEDIUM_GRAY_COLOR));
			return;
		}
		if (rumours.getAssignments() != null)
		{
			for (RumourAssignment a : rumours.getAssignments())
			{
				if (a == null || a.getHunter() == null)
				{
					continue;
				}
				String rumour = a.isKnown() && a.getRumour() != null ? a.getRumour().getName() : "unknown";
				JPanel row = new JPanel(new BorderLayout());
				row.setOpaque(false);
				row.setAlignmentX(Component.LEFT_ALIGNMENT);
				JButton who = linkButton((a.isActive() ? "▶ " : "") + a.getHunter().getName(),
					wikiSearchUrl(a.getHunter().getName()));
				who.setForeground(a.isActive() ? ColorScheme.BRAND_ORANGE : ColorScheme.LIGHT_GRAY_COLOR);
				who.setBorder(BorderFactory.createEmptyBorder(1, 0, 1, 2));
				row.add(who, BorderLayout.WEST);
				if (a.isKnown() && a.getRumour() != null)
				{
					row.add(linkButton(rumour, wikiSearchUrl(rumour)), BorderLayout.EAST);
				}
				else
				{
					JLabel unk = smallLabel("unknown", ColorScheme.MEDIUM_GRAY_COLOR);
					unk.setHorizontalAlignment(SwingConstants.RIGHT);
					row.add(unk, BorderLayout.EAST);
				}
				row.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));
				rumourSection.add(row);
			}
		}
		if (rumours.getCurrentRumour() != null)
		{
			String caught = "Caught: " + rumours.getCaught();
			if (rumours.getPity() != null && rumours.getPity().getCatchesUntilPity() > 0)
			{
				caught += " · " + rumours.getPity().getCatchesUntilPity() + " until pity";
			}
			rumourSection.add(Box.createVerticalStrut(3));
			rumourSection.add(smallLabel(caught, ColorScheme.MEDIUM_GRAY_COLOR));
		}
		if (rumours.isFinished())
		{
			rumourSection.add(smallLabel("✓ Complete — hand it in!", ColorScheme.PROGRESS_COMPLETE_COLOR));
		}
	}

	private static boolean lumbridgeEliteDone(AchievementDiaries diaries)
	{
		if (diaries == null || diaries.getRegions() == null)
		{
			return false;
		}
		for (DiaryRegion r : diaries.getRegions())
		{
			if ("lumbridge_draynor".equals(r.getKey()) || "lumbridge".equals(r.getKey()))
			{
				return r.getElite() != null && r.getElite().isComplete();
			}
		}
		return false;
	}

	/** A blocked creature as its own row: a wiki-linked button. */
	private JButton creatureButton(String name)
	{
		return linkButton("• " + name, wikiSearchUrl(name));
	}

	private JButton linkButton(String text, String url)
	{
		JButton b = new JButton(text);
		b.setFont(FontManager.getRunescapeFont());
		b.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		b.setToolTipText("Open on the OSRS Wiki");
		b.setCursor(new Cursor(Cursor.HAND_CURSOR));
		b.setBorder(BorderFactory.createEmptyBorder(1, 8, 1, 2));
		b.setContentAreaFilled(false);
		b.setFocusPainted(false);
		b.setHorizontalAlignment(SwingConstants.LEFT);
		b.setAlignmentX(Component.LEFT_ALIGNMENT);
		b.setMaximumSize(new Dimension(Integer.MAX_VALUE, b.getPreferredSize().height));
		b.addActionListener(e -> LinkBrowser.browse(url));
		return b;
	}

	private static String wikiSearchUrl(String name)
	{
		try
		{
			return WIKI_SEARCH + URLEncoder.encode(name, "UTF-8");
		}
		catch (UnsupportedEncodingException e)
		{
			return WIKI_SEARCH + name.replace(' ', '+');
		}
	}

	private JLabel slotNote(String text)
	{
		JLabel l = smallLabel(text, ColorScheme.MEDIUM_GRAY_COLOR);
		l.setBorder(BorderFactory.createEmptyBorder(1, 8, 1, 0));
		return l;
	}

	private static String orId(String name, int id)
	{
		return name != null && !name.isEmpty() ? name : "Task #" + id;
	}

	private static JPanel column()
	{
		JPanel p = new JPanel();
		p.setLayout(new BoxLayout(p, BoxLayout.Y_AXIS));
		p.setOpaque(false);
		p.setAlignmentX(Component.LEFT_ALIGNMENT);
		return p;
	}

	private static JLabel smallLabel(String text, java.awt.Color color)
	{
		JLabel l = new JLabel(text);
		l.setFont(FontManager.getRunescapeFont());
		l.setForeground(color);
		l.setAlignmentX(Component.LEFT_ALIGNMENT);
		return l;
	}

	/** A wrapping multi-line label: fills the panel width, breaks long text. */
	private static JLabel wrapLabel(String text, java.awt.Color color)
	{
		JLabel l = new JLabel("<html>" + text + "</html>");
		l.setFont(FontManager.getRunescapeFont());
		l.setForeground(color);
		l.setAlignmentX(Component.LEFT_ALIGNMENT);
		return l;
	}

	private static JLabel sectionTitle(String text)
	{
		JLabel l = new JLabel(text.toUpperCase());
		l.setFont(FontManager.getRunescapeFont());
		l.setForeground(ColorScheme.BRAND_ORANGE);
		l.setBorder(BorderFactory.createEmptyBorder(0, 0, 3, 0));
		l.setAlignmentX(Component.LEFT_ALIGNMENT);
		return l;
	}

	private static void openFolder(File dir)
	{
		try
		{
			if (Desktop.isDesktopSupported())
			{
				Desktop.getDesktop().open(dir);
			}
		}
		catch (Exception e)
		{
			log.debug("Could not open export folder", e);
		}
	}

	/** BorderLayout panel that always matches the scroll viewport's width, so
	 *  content can only grow downward (vertical scrolling, wrapped text). */
	private static class ScrollableColumn extends JPanel implements Scrollable
	{
		ScrollableColumn()
		{
			super(new BorderLayout());
			setBackground(ColorScheme.DARK_GRAY_COLOR);
		}

		@Override
		public Dimension getPreferredScrollableViewportSize()
		{
			return getPreferredSize();
		}

		@Override
		public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return 16;
		}

		@Override
		public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return 64;
		}

		@Override
		public boolean getScrollableTracksViewportWidth()
		{
			return true;
		}

		@Override
		public boolean getScrollableTracksViewportHeight()
		{
			return false;
		}
	}
}

package io.kimpton.accountdataexporter.exporters;

import io.kimpton.accountdataexporter.model.QuestEntry;
import io.kimpton.accountdataexporter.model.Quests;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.gameval.VarPlayerID;

public class QuestsBuilder
{
	@Inject
	private Client client;

	public Quests build()
	{
		int notStarted = 0;
		int inProgress = 0;
		int finished = 0;
		int unknown = 0;
		List<QuestEntry> entries = new ArrayList<>();

		for (Quest quest : Quest.values())
		{
			QuestState state;
			try
			{
				state = quest.getState(client);
			}
			catch (RuntimeException e)
			{
				state = null;
			}

			if (state == QuestState.NOT_STARTED)
			{
				notStarted++;
			}
			else if (state == QuestState.IN_PROGRESS)
			{
				inProgress++;
			}
			else if (state == QuestState.FINISHED)
			{
				finished++;
			}
			else
			{
				unknown++;
			}

			entries.add(new QuestEntry(quest.name(), quest.getName(), state != null ? state.name() : "UNKNOWN"));
		}

		return new Quests(notStarted, inProgress, finished, unknown,
			notStarted + inProgress + finished + unknown,
			client.getVarpValue(VarPlayerID.QP), entries);
	}
}

package io.kimpton.accountdataexporter.exporters;

import io.kimpton.accountdataexporter.model.GeOffer;
import io.kimpton.accountdataexporter.model.GrandExchange;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.client.game.ItemManager;

/** Builds the Grand Exchange section, including a rough estimate of the gp value tied up in
 *  active offers (cash already spent plus the market value of items still to be received). */
public class GrandExchangeBuilder
{
	@Inject
	private Client client;

	@Inject
	private ItemManager itemManager;

	public GrandExchange build()
	{
		GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
		boolean loaded = offers != null;

		int activeCount = 0;
		long listedValueEstimate = 0;
		long accountValueEstimate = 0;
		List<GeOffer> out = new ArrayList<>();

		if (offers != null)
		{
			for (int slot = 0; slot < offers.length; slot++)
			{
				GrandExchangeOffer offer = offers[slot];
				if (offer == null || offer.getState() == null || "EMPTY".equals(offer.getState().name()))
				{
					continue;
				}

				int itemId = offer.getItemId();
				int listedPrice = offer.getPrice();
				int marketPrice = itemId > 0 ? itemManager.getItemPrice(itemId) : 0;
				int totalQuantity = offer.getTotalQuantity();
				int completedQuantity = offer.getQuantitySold();
				int remainingQuantity = Math.max(0, totalQuantity - completedQuantity);
				int spent = offer.getSpent();
				String state = offer.getState().name();

				long offerListed = (long) listedPrice * totalQuantity;
				long offerAccountValue = estimateAccountValue(
					state, marketPrice, listedPrice, totalQuantity, completedQuantity, remainingQuantity, spent);

				activeCount++;
				listedValueEstimate += offerListed;
				accountValueEstimate += offerAccountValue;

				out.add(new GeOffer(
					slot, state, itemId,
					itemId > 0 ? itemManager.getItemComposition(itemId).getName() : "",
					listedPrice, marketPrice, totalQuantity, completedQuantity, remainingQuantity, spent,
					offerListed, offerAccountValue));
			}
		}

		return new GrandExchange(loaded, activeCount, listedValueEstimate, accountValueEstimate, out);
	}

	private long estimateAccountValue(
		String state, int marketPrice, int listedPrice,
		int totalQuantity, int completedQuantity, int remainingQuantity, int spent)
	{
		if (state != null && state.contains("SELL"))
		{
			return (long) spent + ((long) marketPrice * remainingQuantity);
		}
		if (state != null && state.contains("BUY"))
		{
			return ((long) marketPrice * completedQuantity) + ((long) listedPrice * remainingQuantity);
		}
		return (long) marketPrice * totalQuantity;
	}
}

package io.kimpton.accountdataexporter.exporters;

import io.kimpton.accountdataexporter.model.BankTagTab;
import io.kimpton.accountdataexporter.model.BankTags;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/** Builds the Bank Tags section from RuneLite's built-in Bank Tags plugin config
 *  (group "banktags"): the tag-tab list ("tagtabs" CSV), each tab's icon item
 *  ("icon_&lt;tag&gt;"), and the tagged item ids ("item_&lt;id&gt;" = CSV of tags).
 *  available=false when the player has no tag tabs. */
@Slf4j
public class BankTagsBuilder
{
	private static final String GROUP = "banktags";
	private static final String TAG_TABS_KEY = "tagtabs";
	private static final String ICON_PREFIX = "icon_";
	private static final String ITEM_PREFIX = "item_";

	@Inject
	private ConfigManager configManager;

	public BankTags build()
	{
		String tabsCsv = configManager.getConfiguration(GROUP, TAG_TABS_KEY);
		if (tabsCsv == null || tabsCsv.trim().isEmpty())
		{
			return new BankTags(false, new ArrayList<>());
		}

		// tag (standardized lowercase) -> tagged item ids, from every item_<id> key.
		Map<String, List<Integer>> tagItems = new HashMap<>();
		String wholePrefix = GROUP + "." + ITEM_PREFIX;
		for (String wholeKey : configManager.getConfigurationKeys(wholePrefix))
		{
			String idPart = wholeKey.substring(wholeKey.lastIndexOf(ITEM_PREFIX) + ITEM_PREFIX.length());
			int itemId;
			try
			{
				itemId = Integer.parseInt(idPart);
			}
			catch (NumberFormatException e)
			{
				continue;
			}
			String tagsCsv = configManager.getConfiguration(GROUP, ITEM_PREFIX + idPart);
			if (tagsCsv == null)
			{
				continue;
			}
			for (String tag : tagsCsv.split(","))
			{
				String std = standardize(tag);
				if (!std.isEmpty())
				{
					tagItems.computeIfAbsent(std, k -> new ArrayList<>()).add(itemId);
				}
			}
		}

		List<BankTagTab> tabs = new ArrayList<>();
		for (String tab : tabsCsv.split(","))
		{
			String std = standardize(tab);
			if (std.isEmpty())
			{
				continue;
			}
			int icon = parseInt(configManager.getConfiguration(GROUP, ICON_PREFIX + std));
			List<Integer> ids = tagItems.getOrDefault(std, new ArrayList<>());
			tabs.add(new BankTagTab(std, icon, ids));
		}
		return new BankTags(!tabs.isEmpty(), tabs);
	}

	// Mirrors RuneLite Text.standardize: lowercase, trimmed.
	private static String standardize(String s)
	{
		return s == null ? "" : s.trim().toLowerCase(Locale.ROOT);
	}

	private static int parseInt(String s)
	{
		try
		{
			return s == null ? 0 : Integer.parseInt(s.trim());
		}
		catch (NumberFormatException e)
		{
			return 0;
		}
	}
}

package io.kimpton.accountdataexporter.exporters;

import java.io.IOException;
import java.io.InputStream;
import java.util.Properties;

/** Bundled slayer task id → name mapping (dumped from the game cache's
 *  slayer_task DB table). Used as a fallback when the live DB lookup yields
 *  nothing — which is what happens for block-list ids in practice. */
final class SlayerTaskNames
{
	private static final Properties NAMES = load();

	private SlayerTaskNames()
	{
	}

	static String name(int taskId)
	{
		return taskId > 0 ? NAMES.getProperty(String.valueOf(taskId)) : null;
	}

	private static Properties load()
	{
		Properties p = new Properties();
		try (InputStream in = SlayerTaskNames.class.getResourceAsStream(
			"/io/kimpton/accountdataexporter/slayer-task-names.properties"))
		{
			if (in != null)
			{
				p.load(in);
			}
		}
		catch (IOException e)
		{
			// Names then resolve to null; consumers fall back to ids.
		}
		return p;
	}
}

