		rumour("RAZOR_BACKED_KEBBIT", "Razor-backed Kebbit", "NOOSE");
		rumour("SABRE_TOOTHED_KEBBIT", "Sabre-toothed Kebbit", "DEADFALL");
		rumour("GREY_CHINCHOMPA", "Grey Chinchompa", "BOX_TRAP");
