		}
		return RUMOURS.get(key);
	}
}

package io.kimpton.accountdataexporter.exporters;

import io.kimpton.accountdataexporter.model.SlayerBlockSlot;
import io.kimpton.accountdataexporter.model.SlayerMasterBlocks;
import io.kimpton.accountdataexporter.model.SlayerState;
import io.kimpton.accountdataexporter.model.SlayerTask;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;

/** Slayer task, reward unlocks, task extensions, auto-kill toggles, and per-master block lists.
 *  Task/creature names are resolved from the SlayerTask DB table. */
@Slf4j
public class SlayerBuilder
{
	// SLAYER_MASTER varbit value -> assigning master. 0 = no master assigned.
	// The varbit is ordered by when each master was added to the game (the four
	// originals then Duradel, then Nieve/Krystilia/Konar), NOT by combat level —
	// so Duradel is 5 and Nieve is 6. Verified: Krystilia=7 (RuneLite), Konar=8.
	private static final String[] SLAYER_MASTER_NAMES = {
		null, "Turael", "Mazchna", "Vannaka", "Chaeldar", "Duradel", "Nieve", "Krystilia", "Konar quo Maten"
	};

	@Inject
	private Client client;

	// DB-table name lookups are stable per game session — cache them so each
	// export doesn't repeat cache-table scans for every block-list slot.
	private final Map<Integer, String> taskNameCache = new HashMap<>();
	private final Map<Integer, String> areaNameCache = new HashMap<>();
	private final Map<Integer, String> bossNameCache = new HashMap<>();

	public SlayerState build()
	{
		return new SlayerState(
			client.getVarbitValue(VarbitID.SLAYER_POINTS),
			client.getVarbitValue(VarbitID.SLAYER_TASKS_COMPLETED),
			client.getVarbitValue(VarbitID.SLAYER_WILDERNESS_TASKS_COMPLETED),
			buildCurrentTask(),
			buildUnlocks(),
			buildTaskExtensions(),
			buildAutoKill(),
			buildBlockLists());
	}

	private SlayerTask buildCurrentTask()
	{
		int taskId = client.getVarpValue(VarPlayerID.SLAYER_TARGET);
		int amountRemaining = client.getVarpValue(VarPlayerID.SLAYER_COUNT);
		int initialAmount = client.getVarpValue(VarPlayerID.SLAYER_COUNT_ORIGINAL);
		int areaId = client.getVarpValue(VarPlayerID.SLAYER_AREA);
		int masterId = client.getVarbitValue(VarbitID.SLAYER_MASTER);
		int bossId = client.getVarbitValue(VarbitID.SLAYER_TARGET_BOSSID);

		return new SlayerTask(
			taskId > 0 && amountRemaining > 0,
			taskId,
			cachedName(taskNameCache, taskId, this::lookupTaskName),
			amountRemaining,
			initialAmount,
			areaId,
			cachedName(areaNameCache, areaId, this::lookupAreaName),
			masterId,
			masterName(masterId),
			bossId,
			cachedName(bossNameCache, bossId, this::lookupBossName));
	}

	/** Cached id→name resolution. Failed lookups (null) are not cached, so names resolve on a
	 *  later export once the game cache tables are available. */
	private String cachedName(Map<Integer, String> cache, int id, java.util.function.IntFunction<String> lookup)
	{
		if (id <= 0)
		{
			return null;
		}
		String name = cache.get(id);
		if (name != null)
		{
			return name;
		}
		name = lookup.apply(id);
		if (name == null)
		{
			// Live DB lookup came back empty (block-list ids do in practice) —
			// fall back to the bundled game-cache mapping.
			name = SlayerTaskNames.name(id);
		}
		if (name != null)
		{
			cache.put(id, name);
		}
		return name;
	}

	// Decode a boss-slayer-task id (SLAYER_TARGET_BOSSID) into the boss's name,
	// via the SlayerTaskSublist table (boss id -> task row) then the SlayerTask
	// table's name column — the same path RuneLite's Slayer plugin uses. 0 -> null.
	private String lookupBossName(int bossId)
	{
		if (bossId <= 0)
		{
			return null;
		}

		try
		{
			List<Integer> bossRows = client.getDBRowsByValue(DBTableID.SlayerTaskSublist.ID, DBTableID.SlayerTaskSublist.COL_TASK_SUBTABLE_ID, 0, bossId);
			if (bossRows == null || bossRows.isEmpty())
			{
				return null;
			}

			Object[] taskField = client.getDBTableField(bossRows.get(0), DBTableID.SlayerTaskSublist.COL_TASK, 0);
			if (taskField == null || taskField.length == 0 || taskField[0] == null)
			{
				return null;
			}

			int taskRow = ((Number) taskField[0]).intValue();
			Object[] nameField = client.getDBTableField(taskRow, DBTableID.SlayerTask.COL_NAME_UPPERCASE, 0);
			if (nameField == null || nameField.length == 0 || nameField[0] == null)
			{
				return null;
			}

			return String.valueOf(nameField[0]);
		}
		catch (Exception e)
		{
			log.debug("Could not resolve slayer boss name for id {}", bossId, e);
			return null;
		}
	}

	// Decode the Konar slayer-area varp into its human-readable location (the name
	// shown in the in-game slayer helper), via the SlayerArea DB table — the same
	// lookup RuneLite's Slayer plugin uses. 0/none -> null.
	private String lookupAreaName(int areaId)
	{
		if (areaId <= 0)
		{
			return null;
		}

		try
		{
			List<Integer> rows = client.getDBRowsByValue(DBTableID.SlayerArea.ID, DBTableID.SlayerArea.COL_AREA_ID, 0, areaId);
			if (rows == null || rows.isEmpty())
			{
				return null;
			}

			Object[] nameField = client.getDBTableField(rows.get(0), DBTableID.SlayerArea.COL_AREA_NAME_IN_HELPER, 0);
			if (nameField == null || nameField.length == 0 || nameField[0] == null)
			{
				return null;
			}

			return String.valueOf(nameField[0]);
		}
		catch (Exception e)
		{
			log.debug("Could not resolve slayer area name for id {}", areaId, e);
			return null;
		}
	}

	private String masterName(int masterId)
	{
		if (masterId > 0 && masterId < SLAYER_MASTER_NAMES.length)
		{
			return SLAYER_MASTER_NAMES[masterId];
		}
		return null;
	}

	// Reward-shop unlocks (the "Unlock" tab). Each varbit is non-zero once purchased.
	private Map<String, Integer> buildUnlocks()
	{
		Map<String, Integer> u = new LinkedHashMap<>();
		u.put("redDragons", client.getVarbitValue(VarbitID.SLAYER_UNLOCK_REDDRAGONS));
		u.put("mithrilDragons", client.getVarbitValue(VarbitID.SLAYER_UNLOCK_MITHRILDRAGONS));
		u.put("aviansies", client.getVarbitValue(VarbitID.SLAYER_UNLOCK_AVIANSIES));
		u.put("tzhaar", client.getVarbitValue(VarbitID.SLAYER_UNLOCK_TZHAAR));
		u.put("lizardmen", client.getVarbitValue(VarbitID.SLAYER_UNLOCK_LIZARDMEN));
		u.put("basilisks", client.getVarbitValue(VarbitID.SLAYER_UNLOCK_BASILISK));
		u.put("vampyres", client.getVarbitValue(VarbitID.SLAYER_UNLOCK_VAMPYRES));
		u.put("warpedCreatures", client.getVarbitValue(VarbitID.SLAYER_UNLOCK_WARPED_CREATURES));
