			VarbitID.SLAYER_BLOCKED_TURAEL_4, VarbitID.SLAYER_BLOCKED_TURAEL_5, VarbitID.SLAYER_BLOCKED_TURAEL_6,
			VarbitID.SLAYER_BLOCKED_TURAEL_DIARY));
		masters.put("mazchna", masterBlocks(
			VarbitID.SLAYER_BLOCKED_MAZCHNA_1, VarbitID.SLAYER_BLOCKED_MAZCHNA_2, VarbitID.SLAYER_BLOCKED_MAZCHNA_3,
			VarbitID.SLAYER_BLOCKED_MAZCHNA_4, VarbitID.SLAYER_BLOCKED_MAZCHNA_5, VarbitID.SLAYER_BLOCKED_MAZCHNA_6,
			VarbitID.SLAYER_BLOCKED_MAZCHNA_DIARY));
		masters.put("vannaka", masterBlocks(
			VarbitID.SLAYER_BLOCKED_VANNAKA_1, VarbitID.SLAYER_BLOCKED_VANNAKA_2, VarbitID.SLAYER_BLOCKED_VANNAKA_3,
			VarbitID.SLAYER_BLOCKED_VANNAKA_4, VarbitID.SLAYER_BLOCKED_VANNAKA_5, VarbitID.SLAYER_BLOCKED_VANNAKA_6,
			VarbitID.SLAYER_BLOCKED_VANNAKA_DIARY));
		masters.put("chaeldar", masterBlocks(
			VarbitID.SLAYER_BLOCKED_CHAELDAR_1, VarbitID.SLAYER_BLOCKED_CHAELDAR_2, VarbitID.SLAYER_BLOCKED_CHAELDAR_3,
			VarbitID.SLAYER_BLOCKED_CHAELDAR_4, VarbitID.SLAYER_BLOCKED_CHAELDAR_5, VarbitID.SLAYER_BLOCKED_CHAELDAR_6,
			VarbitID.SLAYER_BLOCKED_CHAELDAR_DIARY));
		masters.put("konar", masterBlocks(
			VarbitID.SLAYER_BLOCKED_KONAR_1, VarbitID.SLAYER_BLOCKED_KONAR_2, VarbitID.SLAYER_BLOCKED_KONAR_3,
			VarbitID.SLAYER_BLOCKED_KONAR_4, VarbitID.SLAYER_BLOCKED_KONAR_5, VarbitID.SLAYER_BLOCKED_KONAR_6,
			VarbitID.SLAYER_BLOCKED_KONAR_DIARY));
		masters.put("nieve", masterBlocks(
			VarbitID.SLAYER_BLOCKED_NIEVE_1, VarbitID.SLAYER_BLOCKED_NIEVE_2, VarbitID.SLAYER_BLOCKED_NIEVE_3,
			VarbitID.SLAYER_BLOCKED_NIEVE_4, VarbitID.SLAYER_BLOCKED_NIEVE_5, VarbitID.SLAYER_BLOCKED_NIEVE_6,
			VarbitID.SLAYER_BLOCKED_NIEVE_DIARY));
		masters.put("duradel", masterBlocks(
			VarbitID.SLAYER_BLOCKED_DURADEL_1, VarbitID.SLAYER_BLOCKED_DURADEL_2, VarbitID.SLAYER_BLOCKED_DURADEL_3,
			VarbitID.SLAYER_BLOCKED_DURADEL_4, VarbitID.SLAYER_BLOCKED_DURADEL_5, VarbitID.SLAYER_BLOCKED_DURADEL_6,
			VarbitID.SLAYER_BLOCKED_DURADEL_DIARY));
		masters.put("krystilia", masterBlocks(
			VarbitID.SLAYER_BLOCKED_KRYSTILIA_1, VarbitID.SLAYER_BLOCKED_KRYSTILIA_2, VarbitID.SLAYER_BLOCKED_KRYSTILIA_3,
			VarbitID.SLAYER_BLOCKED_KRYSTILIA_4, VarbitID.SLAYER_BLOCKED_KRYSTILIA_5, VarbitID.SLAYER_BLOCKED_KRYSTILIA_6,
			VarbitID.SLAYER_BLOCKED_KRYSTILIA_DIARY));

		return masters;
	}

	private SlayerMasterBlocks masterBlocks(int s1, int s2, int s3, int s4, int s5, int s6, int diary)
	{
		List<SlayerBlockSlot> slots = new ArrayList<>();
		int[] slotVarbits = {s1, s2, s3, s4, s5, s6};
		for (int i = 0; i < slotVarbits.length; i++)
		{
			slots.add(blockSlot(i + 1, slotVarbits[i]));
		}
		return new SlayerMasterBlocks(slots, blockSlot(0, diary));
	}

	private SlayerBlockSlot blockSlot(int slot, int varbitId)
	{
		int taskId = client.getVarbitValue(varbitId);
		return new SlayerBlockSlot(slot, taskId > 0, taskId, cachedName(taskNameCache, taskId, this::lookupTaskName));
	}

	// Resolves the task/creature name for a SlayerTask id via RuneLite's DB-table API; null if unknown.
	private String lookupTaskName(int taskId)
	{
		if (taskId <= 0)
		{
			return null;
		}

		try
		{
			List<Integer> rows = client.getDBRowsByValue(DBTableID.SlayerTask.ID, DBTableID.SlayerTask.COL_ID, 0, taskId);
			if (rows == null || rows.isEmpty())
			{
				return null;
			}

			Object[] nameField = client.getDBTableField(rows.get(0), DBTableID.SlayerTask.COL_NAME_UPPERCASE, 0);
			if (nameField == null || nameField.length == 0 || nameField[0] == null)
			{
				return null;
			}

			return String.valueOf(nameField[0]);
		}
		catch (Exception e)
		{
			log.debug("Could not resolve slayer task name for id {}", taskId, e);
			return null;
		}
	}
}

package io.kimpton.accountdataexporter.exporters;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import io.kimpton.accountdataexporter.model.InventorySetupExport;
import io.kimpton.accountdataexporter.model.InventorySetups;
import io.kimpton.accountdataexporter.model.SetupItem;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;

/** Builds the Inventory Setups section from the Inventory Setups hub plugin's
 *  config (group "inventorysetups", V3 storage: "setupsOrderV3_" = JSON array of
 *  setup hashes, each setup at "setupsV3_&lt;hash&gt;" as JSON). Item names are
 *  resolved at export time (the plugin doesn't persist them). */
@Slf4j
public class InventorySetupsBuilder
{
	private static final String GROUP = "inventorysetups";
	private static final String ORDER_KEY = "setupsOrderV3_";
	private static final String SETUP_PREFIX = "setupsV3_";

	@Inject
	private ConfigManager configManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private Gson gson;

	// Serialized shapes of the Inventory Setups plugin (unknown fields ignored).
	private static class SItem
	{
		int id;
		Integer q;
		Boolean f;
	}

	private static class SSetup
	{
		List<SItem> inv;
		List<SItem> eq;
		List<SItem> rp;
		List<SItem> bp;
		List<SItem> qv;
		Map<String, SItem> afi;
		String name;
		String notes;
		Boolean fv;
		Integer iId;
		Integer sb;
	}

	public InventorySetups build()
	{
		Set<String> keys = new LinkedHashSet<>();
		String orderJson = configManager.getConfiguration(GROUP, ORDER_KEY);
		if (orderJson != null && !orderJson.trim().isEmpty())
		{
			try
			{
				Type t = new TypeToken<List<String>>() { }.getType();
				List<String> order = gson.fromJson(orderJson, t);
				if (order != null)
				{
					for (String hash : order)
					{
						keys.add(SETUP_PREFIX + hash);
					}
				}
			}
			catch (RuntimeException e)
			{
				log.debug("Could not parse inventory setups order", e);
			}
		}
		// Fallback / catch-all: any setup keys not covered by the order list.
		String wholePrefix = GROUP + "." + SETUP_PREFIX;
		for (String wholeKey : configManager.getConfigurationKeys(wholePrefix))
		{
			keys.add(wholeKey.substring(wholeKey.lastIndexOf(SETUP_PREFIX)));
		}

		List<InventorySetupExport> setups = new ArrayList<>();
		for (String key : keys)
		{
			String json = configManager.getConfiguration(GROUP, key);
			if (json == null || json.trim().isEmpty())
			{
				continue;
			}
			try
			{
				SSetup s = gson.fromJson(json, SSetup.class);
				if (s == null || s.name == null)
				{
					continue;
				}
				List<Integer> extra = new ArrayList<>();
				if (s.afi != null)
				{
					for (SItem it : s.afi.values())
					{
						if (it != null)
						{
							extra.add(it.id);
						}
					}
				}
				setups.add(new InventorySetupExport(
					s.name,
					s.notes,
					Boolean.TRUE.equals(s.fv),
					s.iId != null ? s.iId : 0,
					s.sb != null ? s.sb : 0,
					items(s.inv), items(s.eq), items(s.rp), items(s.bp), items(s.qv),
					extra));
			}
			catch (RuntimeException e)
			{
				log.debug("Could not parse inventory setup {}", key, e);
			}
		}
		return new InventorySetups(!setups.isEmpty(), setups);
	}

	/** Converts a serialized item list to exported items, keeping list indexes as
	 *  slots and skipping null (empty) entries. */
	private List<SetupItem> items(List<SItem> list)
	{
		List<SetupItem> out = new ArrayList<>();
		if (list == null)
		{
			return out;
		}
		for (int slot = 0; slot < list.size(); slot++)
		{
			SItem it = list.get(slot);
			if (it == null || it.id <= 0)
			{
				continue;
			}
			out.add(new SetupItem(slot, it.id, itemName(it.id),
				it.q != null ? it.q : 1, Boolean.TRUE.equals(it.f)));
		}
		return out;
	}

	private String itemName(int id)
	{
		try
		{
			return itemManager.getItemComposition(id).getName();
		}
		catch (RuntimeException e)
		{
			return "";
		}
	}
}

package io.kimpton.accountdataexporter.exporters;

import io.kimpton.accountdataexporter.model.HunterRef;
import io.kimpton.accountdataexporter.model.HunterRumours;
import io.kimpton.accountdataexporter.model.Pity;
import io.kimpton.accountdataexporter.model.RumourAssignment;
import io.kimpton.accountdataexporter.model.RumourRef;
import io.kimpton.accountdataexporter.model.TrapRef;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import net.runelite.client.config.ConfigManager;

/** Builds the Hunter Rumour section by reading the Hunter Rumours plugin's RS-profile config (group
 *  {@value #HR_GROUP}). Returns an {@code available=false} section when that plugin has stored
 *  nothing for the current account. */
public class HunterRumourBuilder
{
	private static final String HR_GROUP = "hunterrumours";

	@Inject
	private ConfigManager configManager;

	public HunterRumours build()
	{
		String activeHunterEnum = cfg("current.hunter");

		List<RumourAssignment> assignments = new ArrayList<>();
		int activeNpcId = HunterRumourReference.npcIdForHunterEnum(activeHunterEnum);
		boolean anyAssignment = false;

		for (HunterRef master : HunterRumourReference.masters())
		{
			String rumourKey = cfg("hunter." + master.getNpcId());
			RumourRef rumour = HunterRumourReference.rumour(rumourKey);
			boolean known = rumour != null;
			anyAssignment |= known;
			assignments.add(new RumourAssignment(master, rumour, known, master.getNpcId() == activeNpcId));
		}

		// No data at all => the Hunter Rumours plugin hasn't tracked anything for this account.
		if (activeHunterEnum == null && !anyAssignment)
		{
			return new HunterRumours(false, null, null, null, 0, false, null, new ArrayList<>());
		}

		HunterRef activeHunter = HunterRumourReference.masterByNpcId(activeNpcId);
		RumourRef currentRumour = activeNpcId != 0 ? HunterRumourReference.rumour(cfg("hunter." + activeNpcId)) : null;
		int caught = parseInt(cfg("current.rumour.caught"));
		boolean finished = "true".equalsIgnoreCase(cfg("current.rumour.finished"));
		Pity pity = buildPity(currentRumour, caught);

		return new HunterRumours(true, cfg("backtoback"), activeHunter, currentRumour, caught, finished, pity, assignments);
	}

	private Pity buildPity(RumourRef rumour, int caught)
	{
		if (rumour == null || rumour.getTrap() == null)
		{
			return null;
		}
		TrapRef trap = rumour.getTrap();
		int untilPity = Math.max(0, trap.getPityThreshold() - caught);
		return new Pity(trap.getPityThreshold(), trap.getPityThresholdWithOutfit(), untilPity);
	}

	private String cfg(String key)
	{
		return configManager.getRSProfileConfiguration(HR_GROUP, key);
	}

	private int parseInt(String value)
	{
		try
		{
			return value == null ? 0 : Integer.parseInt(value.trim());
		}
		catch (NumberFormatException e)
		{
			return 0;
		}
	}
}

package io.kimpton.accountdataexporter.exporters;

import io.kimpton.accountdataexporter.model.CaTask;
import io.kimpton.accountdataexporter.model.CaTier;
import io.kimpton.accountdataexporter.model.CombatAchievements;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.StructComposition;
import net.runelite.api.gameval.VarPlayerID;

/** Combat achievement completion. Each tier is an enum of CA-task structs; per struct, param 1308 is
 *  the task name and 1306 is the task id. Completion is a bitfield spread across 20 varps, indexed by
 *  {@code id / 32} with the bit at {@code id % 32}. */
@Slf4j
public class CombatAchievementBuilder
{
	// Struct param ids on each CA-task struct.
	private static final int PARAM_TASK_NAME = 1308;
	private static final int PARAM_TASK_ID = 1306;

	// Enum ids for the six CA tiers, in order.
	private static final Map<Integer, String> TIER_ENUMS = new LinkedHashMap<>();

	static
	{
		TIER_ENUMS.put(3981, "Easy");
		TIER_ENUMS.put(3982, "Medium");
		TIER_ENUMS.put(3983, "Hard");
		TIER_ENUMS.put(3984, "Elite");
		TIER_ENUMS.put(3985, "Master");
		TIER_ENUMS.put(3986, "Grandmaster");
	}

	private static final int[] COMPLETED_VARPS = {
		VarPlayerID.CA_TASK_COMPLETED_0, VarPlayerID.CA_TASK_COMPLETED_1, VarPlayerID.CA_TASK_COMPLETED_2,
		VarPlayerID.CA_TASK_COMPLETED_3, VarPlayerID.CA_TASK_COMPLETED_4, VarPlayerID.CA_TASK_COMPLETED_5,
		VarPlayerID.CA_TASK_COMPLETED_6, VarPlayerID.CA_TASK_COMPLETED_7, VarPlayerID.CA_TASK_COMPLETED_8,
		VarPlayerID.CA_TASK_COMPLETED_9, VarPlayerID.CA_TASK_COMPLETED_10, VarPlayerID.CA_TASK_COMPLETED_11,
		VarPlayerID.CA_TASK_COMPLETED_12, VarPlayerID.CA_TASK_COMPLETED_13, VarPlayerID.CA_TASK_COMPLETED_14,
		VarPlayerID.CA_TASK_COMPLETED_15, VarPlayerID.CA_TASK_COMPLETED_16, VarPlayerID.CA_TASK_COMPLETED_17,
		VarPlayerID.CA_TASK_COMPLETED_18, VarPlayerID.CA_TASK_COMPLETED_19,
	};

	@Inject
	private Client client;

	// Task definitions (id + name) are static game data — read the enum/struct
	// tables once per tier and only re-check the completion varps per export,
	// instead of walking ~550 struct compositions on the client thread each time.
	private final Map<Integer, List<TaskDef>> tierDefCache = new HashMap<>();
	private boolean warnedEmpty;

	private static final class TaskDef
	{
		final int id;
		final String name;

		TaskDef(int id, String name)
		{
			this.id = id;
			this.name = name;
		}
	}

	/** Builds the CA section. When {@code includeTasks} is false only tier totals are exported
	 *  (the per-task list dominates snapshot size). */
	public CombatAchievements build(boolean includeTasks)
	{
		List<CaTier> tiers = new ArrayList<>();
		int totalCompleted = 0;
		int totalTasks = 0;

		for (Map.Entry<Integer, String> tier : TIER_ENUMS.entrySet())
		{
			List<TaskDef> defs = tierDefs(tier.getKey(), tier.getValue());
			List<CaTask> tasks = includeTasks ? new ArrayList<>(defs.size()) : null;
			int tierCompleted = 0;

			for (TaskDef def : defs)
			{
				boolean completed = isCompleted(def.id);
				if (completed)
				{
					tierCompleted++;
				}
				if (tasks != null)
				{
					tasks.add(new CaTask(def.id, def.name, completed));
				}
			}

			totalCompleted += tierCompleted;
			totalTasks += defs.size();
			tiers.add(new CaTier(tier.getValue(), tierCompleted, defs.size(), tasks));
		}

		if (totalTasks == 0 && !warnedEmpty)
		{
			warnedEmpty = true;
			log.warn("Combat achievements resolved 0 tasks — the tier enum/param ids may have shifted in a game update.");
		}

		return new CombatAchievements(totalCompleted, totalTasks, tiers);
	}

	/** Returns the (cached) task definitions for a tier. A failed/empty read is not cached, so a
	 *  tier that wasn't loaded yet is retried on the next export. */
	private List<TaskDef> tierDefs(int enumId, String tierName)
	{
		List<TaskDef> cached = tierDefCache.get(enumId);
		if (cached != null)
		{
			return cached;
		}

		List<TaskDef> defs = new ArrayList<>();
		try
		{
			EnumComposition tierEnum = client.getEnum(enumId);
			for (int structId : tierEnum.getIntVals())
			{
				StructComposition struct = client.getStructComposition(structId);
				defs.add(new TaskDef(struct.getIntValue(PARAM_TASK_ID), struct.getStringValue(PARAM_TASK_NAME)));
			}
		}
		catch (RuntimeException e)
		{
			log.debug("Could not read combat achievement tier {}", tierName, e);
			return defs;
		}
		if (!defs.isEmpty())
		{
			tierDefCache.put(enumId, defs);
		}
		return defs;
	}

	private boolean isCompleted(int taskId)
	{
		int word = taskId / 32;
		if (word < 0 || word >= COMPLETED_VARPS.length)
		{
			return false;
		}
		return (client.getVarpValue(COMPLETED_VARPS[word]) & (1 << (taskId % 32))) != 0;
	}
}

package io.kimpton.accountdataexporter.exporters;

import io.kimpton.accountdataexporter.model.AchievementDiaries;
import io.kimpton.accountdataexporter.model.DiaryRegion;
import io.kimpton.accountdataexporter.model.DiaryTier;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.VarbitID;

/** Diary completion is read from the per-region reward varbits, which become non-zero once a tier's
 *  reward has been claimed. */
public class AchievementDiaryBuilder
{
	@Inject
	private Client client;

	public AchievementDiaries build()
	{
		List<DiaryRegion> regions = new ArrayList<>();

		regions.add(region("ardougne", "Ardougne", VarbitID.ARDOUGNE_EASY_REWARD, VarbitID.ARDOUGNE_MEDIUM_REWARD, VarbitID.ARDOUGNE_HARD_REWARD, VarbitID.ARDOUGNE_ELITE_REWARD));
		regions.add(region("desert", "Desert", VarbitID.DESERT_EASY_REWARD, VarbitID.DESERT_MEDIUM_REWARD, VarbitID.DESERT_HARD_REWARD, VarbitID.DESERT_ELITE_REWARD));
		regions.add(region("falador", "Falador", VarbitID.FALADOR_EASY_REWARD, VarbitID.FALADOR_MEDIUM_REWARD, VarbitID.FALADOR_HARD_REWARD, VarbitID.FALADOR_ELITE_REWARD));
		regions.add(region("fremennik", "Fremennik", VarbitID.FREMENNIK_EASY_REWARD, VarbitID.FREMENNIK_MEDIUM_REWARD, VarbitID.FREMENNIK_HARD_REWARD, VarbitID.FREMENNIK_ELITE_REWARD));
		regions.add(region("kandarin", "Kandarin", VarbitID.KANDARIN_EASY_REWARD, VarbitID.KANDARIN_MEDIUM_REWARD, VarbitID.KANDARIN_HARD_REWARD, VarbitID.KANDARIN_ELITE_REWARD));
		regions.add(region("karamja", "Karamja", VarbitID.ATJUN_EASY_REWARD, VarbitID.ATJUN_MED_REWARD, VarbitID.ATJUN_HARD_REWARD, VarbitID.KARAMJA_ELITE_REWARD));
		regions.add(region("kourend_kebos", "Kourend & Kebos", VarbitID.KOUREND_EASY_REWARD, VarbitID.KOUREND_MEDIUM_REWARD, VarbitID.KOUREND_HARD_REWARD, VarbitID.KOUREND_ELITE_REWARD));
		regions.add(region("lumbridge_draynor", "Lumbridge & Draynor", VarbitID.LUMBRIDGE_EASY_REWARD, VarbitID.LUMBRIDGE_MEDIUM_REWARD, VarbitID.LUMBRIDGE_HARD_REWARD, VarbitID.LUMBRIDGE_ELITE_REWARD));
		regions.add(region("morytania", "Morytania", VarbitID.MORYTANIA_EASY_REWARD, VarbitID.MORYTANIA_MEDIUM_REWARD, VarbitID.MORYTANIA_HARD_REWARD, VarbitID.MORYTANIA_ELITE_REWARD));
		regions.add(region("varrock", "Varrock", VarbitID.VARROCK_EASY_REWARD, VarbitID.VARROCK_MEDIUM_REWARD, VarbitID.VARROCK_HARD_REWARD, VarbitID.VARROCK_ELITE_REWARD));
		regions.add(region("western_provinces", "Western Provinces", VarbitID.WESTERN_EASY_REWARD, VarbitID.WESTERN_MEDIUM_REWARD, VarbitID.WESTERN_HARD_REWARD, VarbitID.WESTERN_ELITE_REWARD));
		regions.add(region("wilderness", "Wilderness", VarbitID.WILDERNESS_EASY_REWARD, VarbitID.WILDERNESS_MEDIUM_REWARD, VarbitID.WILDERNESS_HARD_REWARD, VarbitID.WILDERNESS_ELITE_REWARD));

		int completedTiers = 0;
		for (DiaryRegion region : regions)
		{
			completedTiers += region.getCompletedTierCount();
		}
		int totalTiers = regions.size() * 4;
		double completionPercent = totalTiers > 0 ? (completedTiers * 100.0) / totalTiers : 0.0;

		return new AchievementDiaries(completedTiers, totalTiers, completionPercent, regions);
	}

	private DiaryRegion region(String key, String name, int easy, int medium, int hard, int elite)
	{
		DiaryTier easyTier = tier(easy);
		DiaryTier mediumTier = tier(medium);
		DiaryTier hardTier = tier(hard);
		DiaryTier eliteTier = tier(elite);

		int completed = (easyTier.isComplete() ? 1 : 0)
			+ (mediumTier.isComplete() ? 1 : 0)
			+ (hardTier.isComplete() ? 1 : 0)
			+ (eliteTier.isComplete() ? 1 : 0);

		return new DiaryRegion(key, name, easyTier, mediumTier, hardTier, eliteTier, completed, 4, completed == 4);
	}

	private DiaryTier tier(int varbitId)
	{
		int value = client.getVarbitValue(varbitId);
		return new DiaryTier(value > 0, value);
	}
}

package io.kimpton.accountdataexporter;

import io.kimpton.accountdataexporter.model.Container;
import java.util.Collections;

/** Retains the last-known-good copy of a single container. Bank/inventory/equipment are only
 *  populated client-side once the player opens them, so when the live container is unavailable we
 *  serve the retained copy flagged {@code fromCache} rather than reporting it empty. */
class ContainerCache
{
	private Container lastGood;
	private long lastSeenTimestamp;

	/** Seeds the cache from a previously persisted snapshot, off the client thread. */
	void seed(Container previous)
	{
		if (previous != null && previous.isLoaded())
		{
			lastGood = previous;
			lastSeenTimestamp = previous.getLastSeenTimestamp() > 0
				? previous.getLastSeenTimestamp()
				: System.currentTimeMillis();
		}
	}

	/** Returns the container to export: the live one if loaded (updating the cache), otherwise the
	 *  last-known-good copy, otherwise an empty unloaded container. */
	Container choose(Container live)
	{
		if (live != null && live.isLoaded())
		{
			lastSeenTimestamp = System.currentTimeMillis();
			lastGood = new Container(true, false, lastSeenTimestamp,
				live.getValue(), live.getItemCount(), live.getItems());
			return lastGood;
		}

		if (lastGood != null)
		{
			return new Container(true, true, lastSeenTimestamp,
				lastGood.getValue(), lastGood.getItemCount(), lastGood.getItems());
		}

		return new Container(false, false, 0, 0, 0, Collections.emptyList());
	}

	void reset()
	{
		lastGood = null;
		lastSeenTimestamp = 0;
	}
}

package io.kimpton.accountdataexporter;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import io.kimpton.accountdataexporter.model.Snapshot;
import java.io.File;
import java.io.IOException;
import java.io.Reader;
import java.io.Writer;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.StandardCopyOption;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;

/** Reads and writes snapshot JSON under {@code .runelite/account-data-exporter/}. All writes happen
 *  on the shared executor, never the client thread, and land atomically via a temp-file rename.
 *  Unchanged snapshots are skipped (compared with volatile fields excluded), with a periodic
 *  heartbeat write so consumers that judge freshness by the embedded timestamp still see the
 *  account as live while the player idles. */
@Slf4j
@Singleton
class SnapshotWriter
{
	private static final String EXPORT_DIR_NAME = "account-data-exporter";
	private static final String LATEST_FILE = "latest.json";

	/** Fields that change every export regardless of game state; excluded from the dirty check. */
	private static final String[] VOLATILE_FIELDS = {"timestamp", "timestampIso", "fps"};

	/** Maximum age of the on-disk snapshot while logged in, even when nothing changed. Must stay
	 *  well under consumers' live-vs-stale threshold (the companion server uses 10 minutes). */
	private static final long HEARTBEAT_MS = 2 * 60 * 1000L;

	@Inject
	private Gson gson;

	@Inject
	private ScheduledExecutorService executor;

	// Dirty-check state; only touched inside the synchronized executor task.
	private String lastRsn;
	private String lastContent;
	private long lastWriteMs;

	File getExportDirectory()
	{
		return new File(RuneLite.RUNELITE_DIR, EXPORT_DIR_NAME);
	}

	/** Queues an asynchronous write of {@code latest.json} and {@code <rsn>.json}. Skips the write
	 *  when nothing but the volatile fields changed since the last one (unless the heartbeat is due),
	 *  which silences the downstream file-watch pipeline while the player idles. */
	void write(String rsn, Snapshot snapshot)
	{
		executor.execute(() ->
		{
			synchronized (this)
			{
				String content = contentKey(snapshot);
				long now = System.currentTimeMillis();
				boolean unchanged = content != null && content.equals(lastContent)
					&& rsn != null && rsn.equals(lastRsn);
				if (unchanged && now - lastWriteMs < HEARTBEAT_MS)
				{
					return;
				}

				File dir = getExportDirectory();
				if (!dir.exists() && !dir.mkdirs())
				{
					log.warn("Could not create export directory: {}", dir.getAbsolutePath());
					return;
				}

				try
				{
					writeAtomically(new File(dir, LATEST_FILE), snapshot);
					writeAtomically(accountFile(dir, rsn), snapshot);
					lastRsn = rsn;
					lastContent = content;
					lastWriteMs = now;
				}
				catch (IOException e)
				{
					log.warn("Failed to write account data export", e);
				}
			}
		});
	}

	/** Serializes the snapshot with the always-changing fields removed, for change detection.
	 *  Returns null if serialization fails (treated as "changed"). */
	private String contentKey(Snapshot snapshot)
	{
		try
		{
			JsonObject tree = gson.toJsonTree(snapshot).getAsJsonObject();
			for (String field : VOLATILE_FIELDS)
			{
				tree.remove(field);
			}
			// Containers refresh lastSeenTimestamp on every export even when their
			// items are identical — ignore it, or nothing would ever look unchanged.
			for (String container : new String[]{"inventory", "equipment", "bank"})
			{
				if (tree.get(container) != null && tree.get(container).isJsonObject())
				{
					tree.getAsJsonObject(container).remove("lastSeenTimestamp");
				}
			}
			return tree.toString();
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	/** Reads the previous on-disk snapshot for an account, or null if absent/unreadable.
	 *  Intended to seed in-memory caches off the client thread. */
	Snapshot loadPrevious(String rsn)
	{
		File file = accountFile(getExportDirectory(), rsn);
		if (!file.exists())
		{
			return null;
		}

		try (Reader reader = Files.newBufferedReader(file.toPath(), StandardCharsets.UTF_8))
		{
			return gson.fromJson(reader, Snapshot.class);
		}
		catch (IOException | RuntimeException e)
		{
			log.debug("Could not read previous snapshot {}", file.getAbsolutePath(), e);
			return null;
		}
	}

	private void writeAtomically(File target, Snapshot snapshot) throws IOException
	{
		File tmp = new File(target.getParentFile(), target.getName() + ".tmp");
		try (Writer writer = Files.newBufferedWriter(tmp.toPath(), StandardCharsets.UTF_8))
		{
			gson.toJson(snapshot, writer);
		}

		try
		{
			Files.move(tmp.toPath(), target.toPath(),
				StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
		}
		catch (IOException e)
		{
			// Some filesystems don't support atomic moves; fall back to a plain replace.
			Files.move(tmp.toPath(), target.toPath(), StandardCopyOption.REPLACE_EXISTING);
		}
	}

	private File accountFile(File dir, String rsn)
	{
		return new File(dir, safeFileName(rsn) + ".json");
	}

	private String safeFileName(String rsn)
	{
		return rsn.replaceAll("[^a-zA-Z0-9 _-]", "_");
	}
}

