package io.kimpton.accountdataexporter;

import io.kimpton.accountdataexporter.model.CombatState;
import io.kimpton.accountdataexporter.model.CombatTarget;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.events.HitsplatApplied;

/** Tracks the local player's current fight from hitsplat events. Combat is considered active while a
 *  hitsplat involving the local player has landed within {@link #COMBAT_TIMEOUT_MS}; damage and
 *  duration are reset whenever a new fight begins after that gap. */
@Singleton
class CombatTracker
{
	private static final long COMBAT_TIMEOUT_MS = 10_000;

	@Inject
	private Client client;

	private long fightStartMs;
	private long lastCombatMs;
	private int damageDealt;
	private int damageTaken;

	void onHitsplat(HitsplatApplied event)
	{
		Player localPlayer = client.getLocalPlayer();
		if (localPlayer == null)
		{
			return;
		}

		Actor actor = event.getActor();
		boolean mine = event.getHitsplat().isMine();
		boolean onMe = actor == localPlayer;

		// Only hits we dealt or hits we took count as our combat.
		if (!mine && !onMe)
		{
			return;
		}

		long now = System.currentTimeMillis();
		if (lastCombatMs == 0 || now - lastCombatMs > COMBAT_TIMEOUT_MS)
		{
			fightStartMs = now;
			damageDealt = 0;
			damageTaken = 0;
		}
		lastCombatMs = now;

		int amount = event.getHitsplat().getAmount();
		if (onMe)
		{
			damageTaken += amount;
		}
		if (mine)
		{
			damageDealt += amount;
		}
	}

	CombatState snapshot()
	{
		long now = System.currentTimeMillis();
		boolean inCombat = lastCombatMs > 0 && now - lastCombatMs <= COMBAT_TIMEOUT_MS;

		if (!inCombat)
		{
			return new CombatState(false, null, 0, 0, 0);
		}

		Player localPlayer = client.getLocalPlayer();
		CombatTarget target = localPlayer != null ? resolveTarget(localPlayer.getInteracting()) : null;
		return new CombatState(true, target, now - fightStartMs, damageDealt, damageTaken);
	}

	void reset()
	{
		fightStartMs = 0;
		lastCombatMs = 0;
		damageDealt = 0;
		damageTaken = 0;
	}

	private CombatTarget resolveTarget(Actor actor)
	{
		if (actor instanceof NPC)
		{
			NPC npc = (NPC) actor;
			int ratio = npc.getHealthRatio();
			int scale = npc.getHealthScale();
			boolean healthPresent = ratio >= 0 && scale > 0;
			Double healthPercent = healthPresent ? Math.round((ratio * 1000.0) / scale) / 10.0 : null;
			return new CombatTarget("npc", npc.getId(), npc.getName(), npc.getCombatLevel(), healthPercent, healthPresent);
		}

		if (actor instanceof Player)
		{
			// Deliberately log no other data about other players.
			return new CombatTarget("player", null, null, null, null, null);
		}

		return null;
	}
}

package io.kimpton.accountdataexporter;

import com.google.inject.Provides;
import io.kimpton.accountdataexporter.model.Snapshot;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;
import javax.swing.SwingUtilities;

@Slf4j
@PluginDescriptor(
	name = "Account Data Exporter",
	description = "Exports local account snapshots to JSON for spreadsheets, account tracking, and personal analytics.",
	tags = {"data", "export", "json", "account", "tracking", "slayer", "combat", "hunter", "rumour", "analytics"}
)
public class AccountDataExporterPlugin extends Plugin
{
	private static final int LOGIN_SETTLE_TICKS = 5;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private AccountDataExporterConfig config;

	@Inject
	private SnapshotService snapshotService;

	@Inject
	private SnapshotWriter snapshotWriter;

	@Inject
	private CombatTracker combatTracker;

	@Inject
	private ClientToolbar clientToolbar;

	private AccountDataExporterPanel panel;
	private NavigationButton navButton;

	private int ticksLoggedIn;
	private int ticksSinceExport;
	private String lastRsn = "";

	@Provides
	AccountDataExporterConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(AccountDataExporterConfig.class);
	}

	@Override
	protected void startUp()
	{
		log.info("Account Data Exporter v{} started.", SnapshotService.EXPORT_VERSION);
		resetSessionState();

		if (config.showSidePanel())
		{
			addPanel();
		}
	}

	@Override
	protected void shutDown()
	{
		log.info("Account Data Exporter stopped.");
		resetSessionState();
		removePanel();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!AccountDataExporterConfig.GROUP.equals(event.getGroup()) || !"showSidePanel".equals(event.getKey()))
		{
			return;
		}
		if (config.showSidePanel())
		{
			addPanel();
		}
		else
		{
			removePanel();
		}
	}

	private void addPanel()
	{
		if (navButton != null)
		{
			return;
		}
		panel = new AccountDataExporterPanel(snapshotWriter.getExportDirectory());
		navButton = NavigationButton.builder()
			.tooltip("Account Data Exporter")
			.icon(ImageUtil.loadImageResource(getClass(), "panel_icon.png"))
			.priority(10)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
	}

	private void removePanel()
	{
		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
			navButton = null;
			panel = null;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		Player localPlayer = client.getLocalPlayer();
		if (client.getGameState() != GameState.LOGGED_IN || localPlayer == null)
		{
			ticksLoggedIn = 0;
			ticksSinceExport = 0;
			return;
		}

		String rsn = localPlayer.getName();
		if (rsn != null && !rsn.equals(lastRsn))
		{
			onAccountChanged(rsn);
		}

		ticksLoggedIn++;
		ticksSinceExport++;

		if (ticksLoggedIn < LOGIN_SETTLE_TICKS || ticksSinceExport < exportIntervalTicks())
		{
			return;
		}

		ticksSinceExport = 0;
		exportSnapshot();
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		combatTracker.onHitsplat(event);
	}

	private void exportSnapshot()
	{
		String exportDir = snapshotWriter.getExportDirectory().getAbsolutePath();
		Snapshot snapshot = snapshotService.build(config, exportDir);
		if (snapshot == null)
		{
			return;
		}

		snapshotWriter.write(snapshot.getRsn(), snapshot);
		if (panel != null)
		{
			final AccountDataExporterPanel p = panel;
			SwingUtilities.invokeLater(() -> p.update(snapshot));
		}
		log.debug("Exported snapshot for {} (world {}, total level {})",
			snapshot.getRsn(), snapshot.getWorld(), snapshot.getTotalLevel());
	}

	private void onAccountChanged(String rsn)
	{
		lastRsn = rsn;
		snapshotService.resetCaches();
		combatTracker.reset();

		// Load the previous on-disk snapshot off-thread, then seed caches back on the client thread.
		executor.execute(() ->
		{
			Snapshot previous = snapshotWriter.loadPrevious(rsn);
			if (previous != null)
			{
				clientThread.invokeLater(() -> snapshotService.seedFromPrevious(previous));
			}
		});
	}

	private void resetSessionState()
	{
		ticksLoggedIn = 0;
		ticksSinceExport = 0;
		lastRsn = "";
		snapshotService.resetCaches();
		combatTracker.reset();
	}

	private int exportIntervalTicks()
	{
		return Math.max(1, config.exportIntervalTicks());
	}
}

